From dbb16a4b7cec3cc2c4345acd944239059ab3fdad Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:17:49 +0100
Subject: [PATCH] applets/quicklaunch: keep dropped URLs until they are
 inserted

Dropping a file or link from outside onto Quicklaunch added nothing, since
the URL list read from the drop event was only used after the drop ended,
when it had become empty. Copy the URLs into an array before deferring.

BUG: 363651
---
 applets/quicklaunch/Popup.qml | 2 +-
 applets/quicklaunch/main.qml  | 2 +-
 2 files changed, 2 insertions(+), 2 deletions(-)

diff --git a/applets/quicklaunch/Popup.qml b/applets/quicklaunch/Popup.qml
index 2224a29b8..4a057e062 100644
--- a/applets/quicklaunch/Popup.qml
+++ b/applets/quicklaunch/Popup.qml
@@ -95,7 +95,7 @@ Item {
             } else if (event.mimeData.hasUrls) {
                 var index = listView.indexAt(event.x, event.y);
                 popupModel.clearDropMarker();
-                var urls = event.mimeData.urls;
+                var urls = Array.from(event.mimeData.urls);
                 event.accept(event.proposedAction);
                 Qt.callLater(function() {
                     popupModel.insertUrls(index == -1 ? popupModel.count : index, urls);
diff --git a/applets/quicklaunch/main.qml b/applets/quicklaunch/main.qml
index 012b52556..36520edf1 100644
--- a/applets/quicklaunch/main.qml
+++ b/applets/quicklaunch/main.qml
@@ -267,7 +267,7 @@ PlasmoidItem {
                 } else {
                     var index = dropArea.gridIndexAt(event.x, event.y);
                     launcherModel.clearDropMarker();
-                    var urls = event.mimeData.urls;
+                    var urls = Array.from(event.mimeData.urls);
                     event.accept(event.proposedAction);
                     Qt.callLater(function() {
                         launcherModel.insertUrls(index == -1 ? launcherModel.count : index, urls);
-- 
